require("monitors_presentation")

-- Hace que algunas apps con datos posiblemente sensibles no se vean al compartir pantalla
streamer_mode = false

-- --- PROGRAMAS ---
terminal = "alacritty"
--$menu = wofi --show drun
--$menu = rofi -show drun
menu = "~/.config/hypr/scripts/rofi_launcher.sh"
fileManager = "dolphin"
screenshot = "grim -g \"$(slurp)\" - | swappy -f -"

-- comandos
poweroff = "hyprshutdown --post-cmd \"systemctl poweroff\""
reboot = "hyprshutdown --post-cmd \"systemctl reboot\""
logout = "hyprshutdown"
--$browser= uwsm app -- brave-browser.desktop
browser = "uwsm app -- com.brave.Origin.beta.desktop"

-- --- AUTOSTART ---
--# para uwsm usar el comando para los programas: uwsm app -- [comando]
--exec = echo $HYPRLAND_INSTANSE_SIGNATURE > /home/stefano/.cache/hyprsignature.txt

-- inhibir el boton de inicio

-- --- APPS DE SISTEMA ---
--exec-once = uwsm app -- /usr/lib/pam_kwallet_init
--exec-once = uwsm app -- xembedsniproxy
--exec-once = uwsm app -- dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP

-- Replay buffer de obs
--exec-once = uwsm app -- obs --minimize-to-tray --startreplaybuffer --scene Replay

-- exec-once = /home/stefano/proyectos/ProyectoAutoCambiadorPerfiles/clanker

-- --- PORTAPAPELES (CLIPBOARD) ---
-- 1. Borrar historial anterior al reiniciar

-- Iniciar servicios de copiado

-- Plugins

-- --- PERMISOS ---
hl.permission({ binary = "/usr/bin/hyprlock", type = "screencopy", mode = "allow" })
hl.permission({ binary = "/usr/(lib|libexec|lib64)/xdg-desktop-portal-hyprland", type = "screencopy", mode = "allow" })

-- Layouts
--workspace = 1, layout:master

hl.env("GDK_SCALE", "1")
hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")

hl.curve("myBezier", { type = "bezier", points = { { 0.05, 0.9 }, { 0.1, 1.05 } } })
hl.animation({
    leaf = "windows",
    enabled = true,
    speed = 7,
    bezier = "myBezier",
})
hl.animation({
    leaf = "windowsOut",
    enabled = true,
    speed = 7,
    bezier = "default",
    style = "popin 80%",
})
hl.animation({
    leaf = "border",
    enabled = true,
    speed = 10,
    bezier = "default",
})
hl.animation({
    leaf = "borderangle",
    enabled = true,
    speed = 8,
    bezier = "default",
})
hl.animation({
    leaf = "fade",
    enabled = true,
    speed = 7,
    bezier = "default",
})
hl.animation({
    leaf = "workspaces",
    enabled = true,
    speed = 6,
    bezier = "default",
})
hl.animation({
    leaf = "layers",
    enabled = false,
})

