hl.on("hyprland.start", function()
    hl.exec_cmd("~/.scripts/sunshine_desk_deactivate.sh")
    hl.exec_cmd("uwsm app -- systemd-inhibit --what=handle-power-key:handle-reboot-key:handle-lid-switch --who=\"Hyprland Session\" --why=\"Custom shutdown/lid handling\" --mode=block Hyprland")
    hl.exec_cmd("uwsm app -- kdeconnect-indicator")
    hl.exec_cmd("uwsm app -- swayosd-server")
    hl.exec_cmd("rm \"$HOME/.cache/cliphist/db\"")
    hl.exec_cmd("uwsm app -- wl-paste --type text --watch cliphist store")
    hl.exec_cmd("uwsm app -- wl-paste --type image --watch cliphist store")
    hl.exec_cmd("hyprpm reload -n")
end)


